app.get("/api/products", (req, res) => {
  const {
    category,
    subcategory,
    search,
    brand,
    minPrice,
    maxPrice,
    sort,
    featured,
    page = "1",
    limit = "24"
  } = req.query;
  let filtered = [...productCatalog];
  if (category) {
    const catQuery = String(category).toLowerCase();
    filtered = filtered.filter((p2) => (p2.category || "").toLowerCase() === catQuery);
  }
  if (subcategory) {
    const subQuery = String(subcategory).toLowerCase();
    filtered = filtered.filter((p2) => (p2.subcategory || "").toLowerCase() === subQuery);
  }
  if (search) {
    const q = String(search).toLowerCase();
    filtered = filtered.filter(
      (p2) => (p2.name || "").toLowerCase().includes(q) || (p2.description || "").toLowerCase().includes(q) || (p2.sku || "").toLowerCase().includes(q) || (p2.brand || "").toLowerCase().includes(q) || (p2.category || "").toLowerCase().includes(q) || (p2.subcategory || "").toLowerCase().includes(q)
    );
  }
  if (brand) {
    const b = String(brand).toLowerCase();
    filtered = filtered.filter((p2) => (p2.brand || "").toLowerCase() === b);
  }
  if (minPrice) {
    const min = parseFloat(String(minPrice));
    if (!isNaN(min)) filtered = filtered.filter((p2) => p2.priceUSD >= min);
  }
  if (maxPrice) {
    const max = parseFloat(String(maxPrice));
    if (!isNaN(max)) filtered = filtered.filter((p2) => p2.priceUSD <= max);
  }
  if (featured === "true") {
    filtered = filtered.filter((p2) => p2.featured || p2.isBestSeller);
  }
  if (sort === "price_asc") {
    filtered.sort((a, b) => a.priceUSD - b.priceUSD);
  } else if (sort === "price_desc") {
    filtered.sort((a, b) => b.priceUSD - a.priceUSD);
  } else if (sort === "rating") {
    filtered.sort((a, b) => b.rating - a.rating);
  } else if (sort === "newest") {
    filtered.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  }
  const p = Math.max(1, parseInt(String(page), 10) || 1);
  const parsedLimit = parseInt(String(limit), 10);
  const l = Math.max(1, Math.min(1e4, isNaN(parsedLimit) ? 24 : parsedLimit));
  const startIndex = (p - 1) * l;
  const paginated = filtered.slice(startIndex, startIndex + l).map((prod, idx) => ({
    ...prod,
    id: prod.id || `prod-${prod.sku ? prod.sku.toLowerCase().replace(/[^a-z0-9]/g, "-") : startIndex + idx}`
  }));
  if (req.query.format === "array") {
    return res.json(paginated);
  }
  res.json({
    products: paginated,
    resultsCount: filtered.length,
    page: p,
    totalPages: Math.ceil(filtered.length / l) || 1
  });
});
